import { AppSelect } from '@/components/ui/AppSelect';
import { useEffect, useMemo, useRef, useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { Archive, CheckCircle2, ChevronRight, Copy, Download, Edit3, Eye, FileQuestion, FileSpreadsheet, Folder, FolderPlus, Plus, Search, Send, Trash2, UploadCloud, X } from 'lucide-react';
import { AdminDialog, AdminEmptyState, AdminPageHeader, AdminSkeleton, AdminStatusBadge, AdminToast, type AdminToastData } from '../AdminUi';
import { AdminDatePicker } from '../AdminDatePicker';
import { questionWorkspaceApi, type BulkQuestionAction, type BulkQuestionResult, type LinkedFile, type QuestionBank, type QuestionKind, type QuestionMode, type QuestionPayload, type WorkspaceQuestion } from './api/questionWorkspaceApi';
import './questions.css';

type Tab = 'overview' | 'add';
type AddMethod = 'manual' | 'excel';
const labels: Record<QuestionKind, string> = { NORMAL_MCQ: 'Normal MCQ', CASE_MCQ: 'Case-based MCQ' };
const options = () => ['A', 'B', 'C', 'D'].map((optionLabel) => ({ optionLabel, html: '' }));
const plain = (html = '') => html.replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
const asHtml = (value: string) => {
  const trimmed = value.trim();
  if (trimmed.startsWith('<')) return trimmed;
  return trimmed
    .split(/\r?\n\s*\r?\n/)
    .map((paragraph) => `<p>${paragraph.replace(/\r?\n/g, '<br />')}</p>`)
    .join('');
};
const fileBase64 = (file: File) => new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result).split(',')[1] ?? ''); reader.onerror = reject; reader.readAsDataURL(file); });
const download = ({ fileName, mimeType, contentBase64 }: { fileName: string; mimeType: string; contentBase64: string }) => { const bytes = Uint8Array.from(atob(contentBase64), (char) => char.charCodeAt(0)); const url = URL.createObjectURL(new Blob([bytes], { type: mimeType })); const anchor = document.createElement('a'); anchor.href = url; anchor.download = fileName; anchor.click(); URL.revokeObjectURL(url); };
const date = (value: string) => new Intl.DateTimeFormat('en-IN', { day: 'numeric', month: 'short', year: 'numeric' }).format(new Date(value));
const uniqueAttemptLabels = (values: Array<string | null | undefined>) => {
  const attempts = new Map<string, string>();
  values.forEach((value) => {
    const label = value?.trim();
    if (label && !attempts.has(label.toLocaleLowerCase())) attempts.set(label.toLocaleLowerCase(), label);
  });
  return [...attempts.values()];
};

export interface QuestionsPageProps { scope?: 'platform' | 'academy'; academyId?: string | null; academyName?: string }

export default function QuestionsPage({ scope = 'platform', academyId, academyName }: QuestionsPageProps) {
  const client = useQueryClient();
  const [tab, setTab] = useState<Tab>('overview');
  const [courseId, setCourseId] = useState('');
  const [search, setSearch] = useState('');
  const [status, setStatus] = useState('');
  const [kind, setKind] = useState('');
  const [collection, setCollection] = useState<'ORIGINAL' | 'QUESTION_BANK'>('ORIGINAL');
  const [bankFilter, setBankFilter] = useState('');
  const [fileFilter, setFileFilter] = useState('');
  const [examFilter, setExamFilter] = useState('');
  const [chapterFilter, setChapterFilter] = useState('');
  const [createdFrom, setCreatedFrom] = useState('');
  const [createdTo, setCreatedTo] = useState('');
  const [updatedFrom, setUpdatedFrom] = useState('');
  const [updatedTo, setUpdatedTo] = useState('');
  const [page, setPage] = useState(1);
  const [editing, setEditing] = useState<WorkspaceQuestion | null>(null);
  const [addBankId, setAddBankId] = useState('');
  const [addBankSectionId, setAddBankSectionId] = useState('');
  const [viewing, setViewing] = useState<WorkspaceQuestion | null>(null);
  const [toast, setToast] = useState<AdminToastData | null>(null);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(() => new Set());
  const [allMatching, setAllMatching] = useState(false);
  const [excludedIds, setExcludedIds] = useState<Set<string>>(() => new Set());
  const [bulkAction, setBulkAction] = useState<BulkQuestionAction | null>(null);
  const [bulkFields, setBulkFields] = useState<Set<'examName' | 'chapterName' | 'conceptName'>>(() => new Set());
  const [bulkValues, setBulkValues] = useState({ examName: '', chapterName: '', conceptName: '' });
  const courses = useQuery({ queryKey: ['question-courses', scope, academyId], queryFn: () => questionWorkspaceApi.courses(scope, academyId), enabled: scope === 'platform' || Boolean(academyId) });
  useEffect(() => { if (!courseId && courses.data?.[0]) setCourseId(courses.data[0].id); }, [courseId, courses.data]);
  useEffect(() => setPage(1), [courseId, search, status, kind, collection, bankFilter, fileFilter, examFilter, chapterFilter, createdFrom, createdTo, updatedFrom, updatedTo]);
  const files = useQuery({ queryKey: ['question-files', scope, academyId, courseId], queryFn: () => questionWorkspaceApi.files(scope, academyId, courseId), enabled: Boolean(courseId) });
  const banks = useQuery({ queryKey: ['question-banks', scope, academyId, courseId], queryFn: () => questionWorkspaceApi.banks(scope, academyId, courseId), enabled: Boolean(courseId) });
  const params = useMemo(() => { const query = new URLSearchParams({ courseId, page: String(page), limit: '25', practiceCollection: collection }); if (bankFilter && collection === 'QUESTION_BANK') query.set('questionBankId', bankFilter); if (search) query.set('search', search); if (status) query.set('status', status); if (kind) query.set('kind', kind); if (fileFilter) query.set('contentItemId', fileFilter); if (examFilter) query.set('examName', examFilter); if (chapterFilter) query.set('chapterName', chapterFilter); if (createdFrom) query.set('createdFrom', `${createdFrom}T00:00:00.000Z`); if (createdTo) query.set('createdTo', `${createdTo}T23:59:59.999Z`); if (updatedFrom) query.set('updatedFrom', `${updatedFrom}T00:00:00.000Z`); if (updatedTo) query.set('updatedTo', `${updatedTo}T23:59:59.999Z`); return query; }, [courseId, page, search, status, kind, collection, bankFilter, fileFilter, examFilter, chapterFilter, createdFrom, createdTo, updatedFrom, updatedTo]);
  const filterParams = useMemo(() => { const query = new URLSearchParams(params); query.delete('page'); query.delete('limit'); return query; }, [params]);
  const filterSignature = filterParams.toString();
  useEffect(() => {
    setSelectedIds(new Set()); setAllMatching(false); setExcludedIds(new Set()); setBulkAction(null);
  }, [scope, academyId, filterSignature]);

  const questions = useQuery({ queryKey: ['questions-workspace', scope, academyId, params.toString()], queryFn: () => questionWorkspaceApi.list(scope, academyId, params), enabled: Boolean(courseId) });
  const notify = (title: string, message: string, tone: AdminToastData['tone'] = 'success') => setToast({ id: String(Date.now()), title, message, tone });
  const refresh = () => client.invalidateQueries({ queryKey: ['questions-workspace', scope, academyId] });
  const lifecycle = useMutation({ mutationFn: ({ id, action }: { id: string; action: 'publish' | 'archive' | 'restore' }) => { if (action === 'archive' && !window.confirm('Archive this question? Students will no longer receive it in practice.')) throw new Error('QUESTION_ARCHIVE_CANCELLED'); return questionWorkspaceApi.lifecycle(scope, academyId, id, action); }, onSuccess: () => { void refresh(); notify('Question updated', 'The lifecycle change is now active.'); }, onError: (error) => { if (error instanceof Error && error.message === 'QUESTION_ARCHIVE_CANCELLED') return; notify('Could not update question', error instanceof Error ? error.message : 'Try again.', 'error'); } });
  const duplicate = useMutation({ mutationFn: (id: string) => questionWorkspaceApi.duplicate(scope, academyId, id), onSuccess: () => { void refresh(); notify('Draft duplicated', 'A linked draft copy was created.'); }, onError: (error) => notify('Could not duplicate', error instanceof Error ? error.message : 'Try again.', 'error') });
  const loadQuestion = useMutation({ mutationFn: (input: { id: string; action: 'view' | 'edit' }) => questionWorkspaceApi.get(scope, academyId, input.id).then((question) => ({ question, action: input.action })), onSuccess: ({ question, action }) => { if (action === 'view') setViewing(question); else { setEditing(question); setTab('add'); } }, onError: (error) => notify('Question could not be opened', error instanceof Error ? error.message : 'Try again.', 'error') });
  const remove = useMutation({ mutationFn: (id: string) => { if (!window.confirm('Delete this question? If it has records with students, it will be archived automatically instead of being permanently deleted.')) throw new Error('QUESTION_DELETE_CANCELLED'); return questionWorkspaceApi.remove(scope, academyId, id); }, onSuccess: (result) => { void refresh(); notify(result.archived ? 'Question archived safely' : 'Question deleted', result.message); }, onError: (error) => { if (error instanceof Error && error.message === 'QUESTION_DELETE_CANCELLED') return; notify('Question could not be deleted', error instanceof Error ? error.message : 'Try again.', 'error'); } });
  const openAdd = (questionBankId = '', questionBankSectionId = '') => { setEditing(null); setAddBankId(questionBankId); setAddBankSectionId(questionBankSectionId); setTab('add'); };
  const selectedCount = allMatching ? Math.max(0, (questions.data?.pagination.total ?? 0) - excludedIds.size) : selectedIds.size;
  const bulk = useMutation({
    mutationFn: ({ action, classification }: { action: BulkQuestionAction; classification?: { examName?: string; chapterName?: string; conceptName?: string } }) => questionWorkspaceApi.bulk(scope, academyId, {
      selection: allMatching ? { mode: 'filter', filters: Object.fromEntries(filterParams), excludeIds: [...excludedIds] } : { mode: 'ids', courseId, ids: [...selectedIds] },
      action, classification,
    }),
    onSuccess: (result: BulkQuestionResult) => {
      const failed = new Set(result.failed.map(({ id }) => id)); setSelectedIds(failed); setAllMatching(false); setExcludedIds(new Set()); setBulkAction(null);
      void refresh();
      const autoArchived = result.succeeded.filter(({ outcome }) => outcome === 'ARCHIVED').length;
      const summary = `${result.succeeded.length} succeeded${autoArchived ? `; ${autoArchived} had student records and were archived automatically instead of being deleted` : ''}${result.failed.length ? `; ${result.failed.length} failed and remain selected` : ''}.`;
      notify(result.failed.length ? 'Bulk action partially completed' : 'Bulk action completed', summary, result.failed.length ? 'error' : 'success');
    },
    onError: (error) => notify('Bulk action could not be completed', error instanceof Error ? error.message : 'Try again.', 'error'),
  });
  const clearSelection = () => { setSelectedIds(new Set()); setAllMatching(false); setExcludedIds(new Set()); setBulkAction(null); };
  const confirmBulk = () => { if (!bulkAction || selectedCount < 1) return; const classification = bulkAction === 'update-classification' ? Object.fromEntries([...bulkFields].map((field) => [field, bulkValues[field]])) : undefined; bulk.mutate({ action: bulkAction, classification }); };

  return <main className="pf-admin-page pf-questions-page">
    <AdminPageHeader title="Questions" description={scope === 'academy' ? `Course-scoped question workspace for ${academyName ?? 'this Academy'}.` : 'Create questions from the same files learners receive through Notes and Store access.'} actions={<button className="pf-admin-button" type="button" onClick={() => openAdd()}><Plus size={17} /> Add questions</button>} />
    <section className="pf-question-coursebar"><label><span>Working course</span><AppSelect className="pf-admin-select" value={courseId} onChange={(event) => setCourseId(event.target.value)} disabled={courses.isLoading}>{courses.data?.map((course: any) => <option key={course.id} value={course.id}>{course.name}</option>)}</AppSelect></label><p>Every file link, import and learner entitlement is restricted to this course.</p></section>
    <nav className="pf-question-tabs" aria-label="Questions workspace"><button type="button" className={tab === 'overview' ? 'is-active' : ''} onClick={() => setTab('overview')}>Overview</button><button type="button" className={tab === 'add' ? 'is-active' : ''} onClick={() => openAdd()}>Add Questions</button></nav>
    {tab === 'overview' ? <section className="pf-question-bank">
      <div className="pf-question-area-picker" aria-label="Question area"><button type="button" className={collection === 'ORIGINAL' ? 'is-active' : ''} onClick={() => setCollection('ORIGINAL')}><strong>MCQs</strong><span>Normal and case-based course practice</span></button><button type="button" className={collection === 'QUESTION_BANK' ? 'is-active' : ''} onClick={() => { setCollection('QUESTION_BANK'); setKind(''); }}><strong>Question Bank</strong><span>Free or Store-entitled question collections</span></button></div>
      {collection === 'QUESTION_BANK' ? <QuestionBankManager scope={scope} academyId={academyId} courseId={courseId} banks={banks.data ?? []} selected={bankFilter} onSelect={setBankFilter} onAddQuestions={openAdd} notify={notify} /> : null}
      <div className="pf-question-filterbar">
        <label className="pf-admin-search-field"><Search size={18} /><input className="pf-admin-input" value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search question or linked file" /></label>
        <AppSelect className="pf-admin-select" value={status} onChange={(event) => setStatus(event.target.value)} aria-label="Status"><option value="">All statuses</option><option value="DRAFT">Draft</option><option value="PUBLISHED">Published</option><option value="ARCHIVED">Archived</option></AppSelect>
        <AppSelect className="pf-admin-select" value={kind} onChange={(event) => setKind(event.target.value)} aria-label="Question type"><option value="">All MCQ types</option><option value="NORMAL_MCQ">Normal MCQ</option><option value="CASE_MCQ">Case-based MCQ</option></AppSelect>
        <AppSelect className="pf-admin-select" value={fileFilter} onChange={(event) => setFileFilter(event.target.value)} aria-label="Linked file"><option value="">All linked files</option>{files.data?.map((file) => <option key={file.id} value={file.id}>{file.name}</option>)}</AppSelect>
        <input className="pf-admin-input" value={examFilter} onChange={(event) => setExamFilter(event.target.value)} placeholder="Exam name" aria-label="Exam name" />
        <input className="pf-admin-input" value={chapterFilter} onChange={(event) => setChapterFilter(event.target.value)} placeholder="Chapter name" aria-label="Chapter name" />
        <label className="pf-question-date-filter"><span>Created from</span><AdminDatePicker value={createdFrom} onChange={setCreatedFrom} placeholder="Start date" /></label>
        <label className="pf-question-date-filter"><span>Created to</span><AdminDatePicker value={createdTo} onChange={setCreatedTo} placeholder="End date" /></label>
        <label className="pf-question-date-filter"><span>Updated from</span><AdminDatePicker value={updatedFrom} onChange={setUpdatedFrom} placeholder="Start date" /></label>
        <label className="pf-question-date-filter"><span>Updated to</span><AdminDatePicker value={updatedTo} onChange={setUpdatedTo} placeholder="End date" /></label>
      </div>
      {questions.isLoading ? <AdminSkeleton rows={7} /> : questions.isError ? <AdminEmptyState icon={<FileQuestion />} title="Questions could not be loaded" description={questions.error instanceof Error ? questions.error.message : 'Try again.'} action={<button className="pf-admin-button" onClick={() => void questions.refetch()}>Try again</button>} /> : questions.data?.data.length ? <BulkQuestionTable data={questions.data.data} page={page} total={questions.data.pagination.total} totalPages={questions.data.pagination.totalPages} selectedIds={selectedIds} setSelectedIds={setSelectedIds} allMatching={allMatching} setAllMatching={setAllMatching} excludedIds={excludedIds} setExcludedIds={setExcludedIds} selectedCount={selectedCount} busy={bulk.isPending} openBulk={setBulkAction} clearSelection={clearSelection} setPage={setPage} view={(id) => loadQuestion.mutate({ id, action: 'view' })} edit={(id) => loadQuestion.mutate({ id, action: 'edit' })} duplicate={(id) => duplicate.mutate(id)} lifecycle={(id, action) => lifecycle.mutate({ id, action })} remove={(id) => remove.mutate(id)} /> : <AdminEmptyState icon={<FileQuestion />} title="No questions in this course" description="Add a manual MCQ or validate an Excel template. Taxonomy folders are intentionally not shown here." action={<button className="pf-admin-button" onClick={() => openAdd(bankFilter)}><Plus size={17} /> Add questions</button>} />}
    </section> : <AddQuestions scope={scope} academyId={academyId} courseId={courseId} files={files.data ?? []} banks={banks.data ?? []} editing={editing} initialQuestionBankId={addBankId} initialQuestionBankSectionId={addBankSectionId} onDone={() => { setEditing(null); setAddBankId(''); setAddBankSectionId(''); setTab('overview'); void refresh(); void banks.refetch(); }} notify={notify} />}
    <AdminDialog open={Boolean(viewing)} onClose={() => setViewing(null)} title="Question details" description={viewing ? `${labels[viewing.kind]} · ${viewing.status} · Created ${date(viewing.createdAt)} · Updated ${date(viewing.updatedAt)}` : ''} size="large">{viewing ? <QuestionDetails question={viewing} /> : null}</AdminDialog>
    <AdminDialog open={Boolean(bulkAction)} onClose={() => { if (!bulk.isPending) setBulkAction(null); }} title={bulkAction === 'update-classification' ? 'Edit selected classifications' : bulkAction === 'delete' ? 'Permanently delete selected questions?' : `${bulkAction === 'restore' ? 'Restore' : bulkAction ? bulkAction[0].toUpperCase() + bulkAction.slice(1) : ''} selected questions?`} description={`${selectedCount} question${selectedCount === 1 ? '' : 's'} will be processed. Each question is validated independently.`} footer={<><button type="button" className="pf-admin-button pf-admin-button--secondary" disabled={bulk.isPending} onClick={() => setBulkAction(null)}>Cancel</button><button type="button" className={`pf-admin-button${bulkAction === 'delete' ? ' pf-admin-button--danger' : ''}`} disabled={bulk.isPending || selectedCount < 1 || (bulkAction === 'update-classification' && bulkFields.size === 0)} onClick={confirmBulk}>{bulk.isPending ? 'Processing…' : 'Confirm action'}</button></>}>
      {bulkAction === 'update-classification' ? <div className="pf-question-bulk-edit"><p>Only checked fields will change. Question text, options, answers, explanations, linked files, and Question Bank status remain untouched.</p>{(['examName', 'chapterName', 'conceptName'] as const).map((field) => <label key={field}><span><input type="checkbox" checked={bulkFields.has(field)} onChange={() => setBulkFields((current) => { const next = new Set(current); next.has(field) ? next.delete(field) : next.add(field); return next; })} /> {field === 'examName' ? 'Exam name' : field === 'chapterName' ? 'Chapter name' : 'Concept name'}</span><input className="pf-admin-input" value={bulkValues[field]} disabled={!bulkFields.has(field) || bulk.isPending} maxLength={field === 'examName' ? 160 : 240} onChange={(event) => setBulkValues((current) => ({ ...current, [field]: event.target.value }))} aria-label={`New ${field === 'examName' ? 'exam name' : field === 'chapterName' ? 'chapter name' : 'concept name'}`} /></label>)}</div> : <div className="pf-question-bulk-confirm">
        <p>{bulkAction === 'delete' ? 'Questions without student records will be permanently deleted. Questions with student records will be archived automatically instead.' : bulkAction === 'archive' ? 'Archived questions stop appearing in student practice, Revisit, and Wrong Answers. Active sessions can still finish from their stored snapshots.' : bulkAction === 'publish' ? 'Only valid draft questions will be published. Required file-link rules still apply.' : 'Only archived questions will be restored to Draft.'}</p>
        <strong>No unselected question will be changed.</strong>
      </div>}
    </AdminDialog>
    <AdminToast toast={toast} onDismiss={() => setToast(null)} />
  </main>;
}

function SelectionCheckbox({ checked, indeterminate = false, label, disabled = false, onChange }: { checked: boolean; indeterminate?: boolean; label: string; disabled?: boolean; onChange: () => void }) {
  const ref = useRef<HTMLInputElement>(null);
  useEffect(() => { if (ref.current) ref.current.indeterminate = indeterminate; }, [indeterminate]);
  return <input ref={ref} className="pf-question-select" type="checkbox" checked={checked} disabled={disabled} aria-label={label} onChange={onChange} />;
}

function BulkQuestionTable({ data, page, total, totalPages, selectedIds, setSelectedIds, allMatching, setAllMatching, excludedIds, setExcludedIds, selectedCount, busy, openBulk, clearSelection, setPage, view, edit, duplicate, lifecycle, remove }: {
  data: WorkspaceQuestion[]; page: number; total: number; totalPages: number;
  selectedIds: Set<string>; setSelectedIds: React.Dispatch<React.SetStateAction<Set<string>>>;
  allMatching: boolean; setAllMatching: React.Dispatch<React.SetStateAction<boolean>>;
  excludedIds: Set<string>; setExcludedIds: React.Dispatch<React.SetStateAction<Set<string>>>;
  selectedCount: number; busy: boolean; openBulk: (action: BulkQuestionAction) => void; clearSelection: () => void; setPage: React.Dispatch<React.SetStateAction<number>>;
  view: (id: string) => void; edit: (id: string) => void; duplicate: (id: string) => void; lifecycle: (id: string, action: 'publish' | 'archive' | 'restore') => void; remove: (id: string) => void;
}) {
  const pageIds = data.map(({ id }) => id);
  const isSelected = (id: string) => allMatching ? !excludedIds.has(id) : selectedIds.has(id);
  const selectedOnPage = pageIds.filter(isSelected).length;
  const allPageSelected = pageIds.length > 0 && selectedOnPage === pageIds.length;
  const togglePage = () => {
    if (allMatching) setExcludedIds((current) => { const next = new Set(current); pageIds.forEach((id) => allPageSelected ? next.add(id) : next.delete(id)); return next; });
    else setSelectedIds((current) => { const next = new Set(current); pageIds.forEach((id) => allPageSelected ? next.delete(id) : next.add(id)); return next; });
  };
  const toggleRow = (id: string) => {
    if (allMatching) setExcludedIds((current) => { const next = new Set(current); next.has(id) ? next.delete(id) : next.add(id); return next; });
    else setSelectedIds((current) => { const next = new Set(current); next.has(id) ? next.delete(id) : next.add(id); return next; });
  };
  return <>
    {selectedCount > 0 ? <div className="pf-question-bulkbar" role="region" aria-label="Bulk question actions"><div className="pf-question-bulkbar__selection"><strong>{selectedCount} selected</strong><button type="button" className="pf-question-bulkbar__clear" disabled={busy} onClick={clearSelection}>Clear selection</button>{!allMatching && allPageSelected && total > pageIds.length ? <button type="button" onClick={() => { setAllMatching(true); setSelectedIds(new Set()); setExcludedIds(new Set()); }}>Select all {total} matching questions</button> : null}</div><div className="pf-question-bulkbar__actions"><button type="button" disabled={busy} onClick={() => openBulk('update-classification')}><Edit3 /> Edit classification</button><button type="button" disabled={busy} onClick={() => openBulk('publish')}><Send /> Publish</button><button type="button" disabled={busy} onClick={() => openBulk('restore')}><CheckCircle2 /> Restore to draft</button><button type="button" disabled={busy} onClick={() => openBulk('archive')}><Archive /> Archive</button><button type="button" className="is-danger" disabled={busy} onClick={() => openBulk('delete')}><Trash2 /> Delete</button></div></div> : null}
    <div className="pf-question-table-wrap"><table className="pf-admin-table pf-question-table"><thead><tr><th className="pf-question-select-column"><SelectionCheckbox checked={allPageSelected} indeterminate={selectedOnPage > 0 && !allPageSelected} label="Select all questions on this page" disabled={busy} onChange={togglePage} /></th><th>Question</th><th>Classification</th><th>Linked files</th><th>Type</th><th>Status</th><th>Created</th><th>Updated</th><th>Actions</th></tr></thead><tbody>{data.map((question) => <tr key={question.id} className={isSelected(question.id) ? 'is-selected' : ''}><td className="pf-question-select-column"><SelectionCheckbox checked={isSelected(question.id)} label={`Select ${plain(question.kind === 'CASE_MCQ' ? question.caseHtml : question.questionHtml) || 'question'}`} disabled={busy} onChange={() => toggleRow(question.id)} /></td><td><button type="button" className="pf-question-title-button" onClick={() => view(question.id)}><strong>{plain(question.kind === 'CASE_MCQ' ? question.caseHtml : question.questionHtml) || 'Untitled question'}</strong>{question.kind === 'CASE_MCQ' ? <small>{question.subQuestions.length} sub-questions</small> : null}</button></td><td><div className="pf-question-classification-cell"><strong>{question.examName || 'Unclassified exam'}</strong><span>{question.chapterName || 'Unclassified chapter'}</span></div></td><td><div className="pf-question-filechips">{question.contentLinks.map((link) => <span key={link.contentItemId}>{link.contentItem.name}</span>)}</div></td><td>{labels[question.kind]}</td><td><AdminStatusBadge tone={question.status === 'PUBLISHED' ? 'success' : question.status === 'DRAFT' ? 'warning' : 'neutral'}>{question.status}</AdminStatusBadge></td><td>{date(question.createdAt)}</td><td>{date(question.updatedAt)}</td><td><div className="pf-question-row-actions"><button aria-label="View" disabled={busy} onClick={() => view(question.id)}><Eye /></button><button aria-label="Edit" disabled={busy} onClick={() => edit(question.id)}><Edit3 /></button><button aria-label="Duplicate" disabled={busy} onClick={() => duplicate(question.id)}><Copy /></button>{question.status === 'DRAFT' ? <button aria-label="Publish" disabled={busy} onClick={() => lifecycle(question.id, 'publish')}><Send /></button> : null}{question.status !== 'ARCHIVED' ? <button aria-label="Archive" disabled={busy} onClick={() => lifecycle(question.id, 'archive')}><Archive /></button> : <button aria-label="Restore" disabled={busy} onClick={() => lifecycle(question.id, 'restore')}><CheckCircle2 /></button>}<button aria-label="Delete permanently" disabled={busy} onClick={() => remove(question.id)}><Trash2 /></button></div></td></tr>)}</tbody></table></div>
    <footer className="pf-question-pagination"><span>{total} questions</span><div><button disabled={page <= 1 || busy} onClick={() => setPage((value) => value - 1)}>Previous</button><span>Page {page} of {Math.max(1, totalPages)}</span><button disabled={page >= totalPages || busy} onClick={() => setPage((value) => value + 1)}>Next</button></div></footer>
  </>;
}

function FilePicker({ files, selected, onChange, required = true }: { files: LinkedFile[]; selected: string[]; onChange: (ids: string[]) => void; required?: boolean }) {
  const [search, setSearch] = useState(''); const visible = files.filter((file) => file.name.toLocaleLowerCase().includes(search.toLocaleLowerCase()));
  return <section className="pf-question-files"><header><div><strong>Linked files{required ? '' : ' (optional)'}</strong><span>{required ? 'One or more files from this course are required.' : 'Question Bank access is controlled by its entitlement. Link files only when they are useful supporting material.'}</span></div><input className="pf-admin-input" value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Find a file" /></header><div>{visible.map((file) => <label key={file.id} className={selected.includes(file.id) ? 'is-selected' : ''}><input type="checkbox" checked={selected.includes(file.id)} onChange={() => onChange(selected.includes(file.id) ? selected.filter((id) => id !== file.id) : [...selected, file.id])} /><span><strong>{file.name}</strong><small>{file.accessType} · {file.mimeType || 'file'}</small></span></label>)}</div></section>;
}

function QuestionBankManager({ scope, academyId, courseId, banks, selected, onSelect, onAddQuestions, notify }: { scope: 'platform' | 'academy'; academyId?: string | null; courseId: string; banks: QuestionBank[]; selected: string; onSelect: (id: string) => void; onAddQuestions: (id?: string, sectionId?: string) => void; notify: (title: string, message: string, tone?: AdminToastData['tone']) => void }) {
  const client = useQueryClient();
  const commercial = scope === 'platform';
  const [creating, setCreating] = useState(false);
  const [editingBankId, setEditingBankId] = useState('');
  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [accessType, setAccessType] = useState<'FREE' | 'PAID'>('FREE');
  const [price, setPrice] = useState('');
  const [durationMode, setDurationMode] = useState<'PERMANENT' | 'LIMITED'>('PERMANENT');
  const [durationValue, setDurationValue] = useState('');
  const [durationUnit, setDurationUnit] = useState<'DAYS' | 'WEEKS' | 'MONTHS'>('MONTHS');
  const refresh = () => client.invalidateQueries({ queryKey: ['question-banks', scope, academyId, courseId] });
  const resetForm = () => { setCreating(false); setEditingBankId(''); setName(''); setDescription(''); setAccessType('FREE'); setPrice(''); setDurationMode('PERMANENT'); setDurationValue(''); setDurationUnit('MONTHS'); };
  const beginCreate = () => { resetForm(); setCreating(true); };
  const beginEdit = (bank: QuestionBank) => { setEditingBankId(bank.id); setName(bank.name); setDescription(bank.description ?? ''); setAccessType(commercial ? bank.accessType : 'FREE'); setPrice(commercial && bank.accessType === 'PAID' ? String(bank.price) : ''); setDurationMode(commercial && bank.accessDurationValue && bank.accessDurationUnit ? 'LIMITED' : 'PERMANENT'); setDurationValue(commercial && bank.accessDurationValue ? String(bank.accessDurationValue) : ''); setDurationUnit(bank.accessDurationUnit ?? 'MONTHS'); setCreating(true); };
  const saveBank = useMutation({ mutationFn: () => { const effectiveAccess = commercial ? accessType : 'FREE'; const paid = effectiveAccess === 'PAID'; const limited = paid && durationMode === 'LIMITED'; const payload = { courseId, name, description, accessType: effectiveAccess, price: paid ? Number(price) : null, accessDurationValue: limited ? Number(durationValue) : null, accessDurationUnit: limited ? durationUnit : null } as const; return editingBankId ? questionWorkspaceApi.updateBank(scope, academyId, editingBankId, payload) : questionWorkspaceApi.createBank(scope, academyId, payload); }, onSuccess: (bank) => { const wasEditing = Boolean(editingBankId); onSelect(bank.id); resetForm(); void refresh(); notify(wasEditing ? 'Question Bank updated' : 'Question Bank created', wasEditing ? 'The collection details and access rules were saved.' : 'Normal and case-based questions can now be added manually or through Excel import.'); }, onError: (error) => notify('Question Bank could not be saved', error instanceof Error ? error.message : 'Review the bank details.', 'error') });
  const lifecycle = useMutation({ mutationFn: ({ id, action }: { id: string; action: 'publish' | 'archive' | 'restore' }) => questionWorkspaceApi.bankLifecycle(scope, academyId, id, action), onSuccess: (_, input) => { if (input.action === 'archive' && selected === input.id) onSelect(''); void refresh(); notify('Question Bank updated', `The bank is now ${input.action === 'publish' ? 'available to eligible students' : input.action === 'archive' ? 'archived' : 'restored as a draft'}.`); }, onError: (error) => notify('Question Bank could not be updated', error instanceof Error ? error.message : 'Try again.', 'error') });
  const removeBank = useMutation({ mutationFn: (id: string) => questionWorkspaceApi.removeBank(scope, academyId, id), onSuccess: () => { onSelect(''); void refresh(); notify('Question Bank deleted', 'The empty draft bank was permanently deleted.'); }, onError: (error) => notify('Question Bank could not be deleted', error instanceof Error ? error.message : 'Archive banks that already have records.', 'error') });
  const current = banks.find((bank) => bank.id === selected);
  const publishBlocked = current?.status === 'DRAFT' && current._count.questions === 0;
  const validPrice = Number.isFinite(Number(price)) && Number(price) > 0;
  const validDuration = durationMode === 'PERMANENT' || (Number.isInteger(Number(durationValue)) && Number(durationValue) > 0);
  const valid = name.trim().length >= 2 && (!commercial || accessType === 'FREE' || (validPrice && validDuration));
  return <section className="pf-question-bank-manager">
    <div className="pf-question-bank-manager__select">
      <div><small>ACTIVE QUESTION BANK</small><strong>{current?.name ?? 'All Question Banks'}</strong><span>{current ? `${current._count.questions} questions · ${current._count.sections ?? 0} subsections · Normal + case-based MCQs · ${current.accessType}${current.accessType === 'PAID' ? ` · ₹${Number(current.price).toLocaleString('en-IN')} · ${current.accessDurationValue && current.accessDurationUnit ? `${current.accessDurationValue} ${current.accessDurationUnit.toLowerCase()}` : 'Permanent access'}` : ''}` : 'Select a bank to filter, edit or organise questions.'}</span>{current?.description ? <p>{current.description}</p> : null}</div>
      <AppSelect className="pf-admin-select" value={selected} onChange={(event) => onSelect(event.target.value)}><option value="">All Question Banks</option>{banks.map((bank) => <option key={bank.id} value={bank.id}>{bank.name} · {bank.status} · {bank.accessType}</option>)}</AppSelect>
      <button type="button" className="pf-admin-button pf-admin-button--secondary" onClick={beginCreate}><Plus size={16} /> New bank</button>
    </div>
    {current ? <>
      <div className="pf-question-bank-manager__actions">
        <AdminStatusBadge tone={current.status === 'PUBLISHED' ? 'success' : 'warning'}>{current.status}</AdminStatusBadge>
        <button type="button" onClick={() => beginEdit(current)}><Edit3 size={15} /> Edit details</button>
        <button type="button" onClick={() => onAddQuestions(current.id)}><Plus size={15} /> Add questions</button>
        {current.status === 'DRAFT' ? <button type="button" disabled={publishBlocked || lifecycle.isPending} title={publishBlocked ? 'Publish at least one question in this bank first.' : undefined} onClick={() => lifecycle.mutate({ id: current.id, action: 'publish' })}>Publish bank</button> : current.status === 'ARCHIVED' ? <button type="button" disabled={lifecycle.isPending} onClick={() => lifecycle.mutate({ id: current.id, action: 'restore' })}>Restore bank</button> : <button type="button" disabled={lifecycle.isPending} onClick={() => lifecycle.mutate({ id: current.id, action: 'archive' })}>Archive bank</button>}
        {current.status === 'DRAFT' && current._count.questions === 0 ? <button type="button" className="pf-question-bank-manager__danger" disabled={removeBank.isPending} onClick={() => { if (window.confirm(`Permanently delete the empty draft Question Bank “${current.name}”?`)) removeBank.mutate(current.id); }}>Delete empty draft</button> : null}
      </div>
      {publishBlocked ? <div className="pf-question-bank-manager__readiness" role="status"><strong>Bank not ready to publish</strong><span>Add and publish at least one question. Empty banks remain drafts and are never shown in the Store or student app.</span><button type="button" onClick={() => onAddQuestions(current.id)}>Add the first question</button></div> : null}
      <QuestionBankDrive scope={scope} academyId={academyId} bank={current} onAddQuestions={onAddQuestions} notify={notify} />
    </> : null}
    {creating ? <div className="pf-question-bank-create">
      <label className="pf-admin-field"><span>Bank name</span><input className="pf-admin-input" value={name} onChange={(event) => setName(event.target.value)} placeholder="e.g. CA Inter Mock Question Bank" /></label>
      <label className="pf-admin-field"><span>Description</span><input className="pf-admin-input" value={description} onChange={(event) => setDescription(event.target.value)} placeholder="What this collection prepares students for" /></label>
      <div className="pf-question-bank-create__notice"><strong>Mixed question collection</strong><span>Normal and case-based MCQs may coexist. Each question belongs only to this bank.</span></div>
      {commercial ? <><label className="pf-admin-field"><span>Access</span><AppSelect className="pf-admin-select" value={accessType} onChange={(event) => { setAccessType(event.target.value as 'FREE' | 'PAID'); setPrice(''); setDurationMode('PERMANENT'); setDurationValue(''); }}><option value="FREE">Free for eligible course students</option><option value="PAID">Paid Question Bank in Store</option></AppSelect></label>{accessType === 'PAID' ? <><label className="pf-admin-field"><span>Price (₹)</span><input className="pf-admin-input" inputMode="decimal" type="number" min="1" step="0.01" value={price} onChange={(event) => setPrice(event.target.value)} placeholder="499" /></label><label className="pf-admin-field"><span>Access validity</span><AppSelect className="pf-admin-select" value={durationMode} onChange={(event) => setDurationMode(event.target.value as 'PERMANENT' | 'LIMITED')}><option value="PERMANENT">Permanent access</option><option value="LIMITED">Limited duration after purchase</option></AppSelect></label>{durationMode === 'LIMITED' ? <div className="pf-question-bank-create__duration"><label className="pf-admin-field"><span>Duration</span><input className="pf-admin-input" inputMode="numeric" type="number" min="1" step="1" value={durationValue} onChange={(event) => setDurationValue(event.target.value)} placeholder="6" /></label><label className="pf-admin-field"><span>Unit</span><AppSelect className="pf-admin-select" value={durationUnit} onChange={(event) => setDurationUnit(event.target.value as 'DAYS' | 'WEEKS' | 'MONTHS')}><option value="DAYS">Days</option><option value="WEEKS">Weeks</option><option value="MONTHS">Months</option></AppSelect></label></div> : null}<div className="pf-question-bank-create__notice"><strong>Direct Store product</strong><span>This Question Bank has its own price and entitlement. It is not attached to a Notes package.</span></div></> : null}</> : null}
      <div className="pf-question-bank-create__actions"><button type="button" onClick={resetForm}>Cancel</button><button type="button" className="pf-admin-button" disabled={!valid || saveBank.isPending} onClick={() => saveBank.mutate()}>{saveBank.isPending ? 'Saving…' : editingBankId ? 'Save changes' : 'Create Question Bank'}</button></div>
    </div> : null}
  </section>;
}

function QuestionBankDrive({ scope, academyId, bank, onAddQuestions, notify }: { scope: 'platform' | 'academy'; academyId?: string | null; bank: QuestionBank; onAddQuestions: (bankId?: string, sectionId?: string) => void; notify: (title: string, message: string, tone?: AdminToastData['tone']) => void }) {
  const [parentId, setParentId] = useState<string | null>(null);
  const [creating, setCreating] = useState(false);
  const [newName, setNewName] = useState('');
  const [renaming, setRenaming] = useState<{ id: string; name: string } | null>(null);
  const [moveItem, setMoveItem] = useState<{ kind: 'section' | 'question'; id: string; name: string } | null>(null);
  const [moveTarget, setMoveTarget] = useState('');
  useEffect(() => { setParentId(null); setCreating(false); setRenaming(null); setMoveItem(null); }, [bank.id]);
  const location = useQuery({ queryKey: ['question-bank-location', scope, academyId, bank.id, parentId], queryFn: () => questionWorkspaceApi.bankLocation(scope, academyId, bank.id, parentId) });
  const refresh = () => location.refetch();
  const createSection = useMutation({ mutationFn: () => questionWorkspaceApi.createBankSection(scope, academyId, bank.id, { parentId, name: newName }), onSuccess: () => { setNewName(''); setCreating(false); void refresh(); notify('Subsection created', 'The new folder is ready for nested subsections or questions.'); }, onError: (error) => notify('Subsection could not be created', error instanceof Error ? error.message : 'Try again.', 'error') });
  const renameSection = useMutation({ mutationFn: () => questionWorkspaceApi.updateBankSection(scope, academyId, bank.id, renaming!.id, { name: renaming!.name }), onSuccess: () => { setRenaming(null); void refresh(); notify('Subsection renamed', 'The new name is visible to admins and students.'); }, onError: (error) => notify('Subsection could not be renamed', error instanceof Error ? error.message : 'Try again.', 'error') });
  const removeSection = useMutation({ mutationFn: (sectionId: string) => questionWorkspaceApi.removeBankSection(scope, academyId, bank.id, sectionId), onSuccess: () => { void refresh(); notify('Subsection deleted', 'The empty subsection was removed.'); }, onError: (error) => notify('Subsection could not be deleted', error instanceof Error ? error.message : 'Move its contents first.', 'error') });
  const move = useMutation({ mutationFn: async () => { if (moveItem?.kind === 'section') await questionWorkspaceApi.updateBankSection(scope, academyId, bank.id, moveItem.id, { parentId: moveTarget || null }); else await questionWorkspaceApi.moveBankQuestions(scope, academyId, bank.id, [moveItem!.id], moveTarget || null); }, onSuccess: () => { setMoveItem(null); setMoveTarget(''); void refresh(); notify('Item moved', 'The Question Bank hierarchy was updated safely.'); }, onError: (error) => notify('Item could not be moved', error instanceof Error ? error.message : 'Choose another destination.', 'error') });
  const data = location.data ? { ...location.data, sections: location.data.sections ?? [], questions: location.data.questions ?? [], allSections: location.data.allSections ?? [], breadcrumbs: location.data.breadcrumbs ?? [{ id: null, name: bank.name }], childSectionLimit: location.data.childSectionLimit ?? 7, maxDepth: location.data.maxDepth ?? 5, depth: location.data.depth ?? 0 } : undefined;
  const sections = data?.sections ?? [];
  const questions = data?.questions ?? [];
  const allSections = data?.allSections ?? [];
  const breadcrumbs = data?.breadcrumbs ?? [{ id: null, name: bank.name }];
  const hasQuestions = Boolean(questions.length);
  const hasSections = Boolean(sections.length);
  const canCreateSection = bank.status !== 'ARCHIVED' && !hasQuestions && Boolean(data) && (data?.depth ?? 0) < (data?.maxDepth ?? 5) && sections.length < (data?.childSectionLimit ?? 7);
  const canAddQuestions = bank.status !== 'ARCHIVED' && !hasSections;
  const moveDestinations = moveItem?.kind === 'question' ? allSections.filter((section) => section._count.children === 0) : allSections.filter((section) => section._count.questions === 0 && section.id !== moveItem?.id);
  return <section className="pf-question-bank-drive">
    <header><div><small>QUESTION BANK CONTENT</small><strong>{data?.breadcrumbs.map((item) => item.name).join(' / ') ?? bank.name}</strong><span>{data ? `${data.sections.length}/${data.childSectionLimit} child subsections created · ${Math.max(0, data.childSectionLimit - data.sections.length)} remaining here` : 'Loading hierarchy…'}</span></div><div><button type="button" className="pf-admin-button pf-admin-button--secondary" disabled={!canCreateSection} onClick={() => setCreating(true)}><FolderPlus size={16} /> New subsection</button><button type="button" className="pf-admin-button" disabled={!canAddQuestions} onClick={() => onAddQuestions(bank.id, parentId ?? '')}><Plus size={16} /> Add questions here</button></div></header>
    {data ? <nav className="pf-question-bank-breadcrumbs" aria-label="Question Bank path">{data.breadcrumbs.map((item, index) => <button type="button" key={item.id ?? 'root'} onClick={() => setParentId(item.id)}>{index ? <ChevronRight size={14} /> : null}{item.name}</button>)}</nav> : null}
    {creating ? <div className="pf-question-bank-drive__create"><input className="pf-admin-input" autoFocus maxLength={160} value={newName} onChange={(event) => setNewName(event.target.value)} placeholder="Subsection name" /><button type="button" onClick={() => { setCreating(false); setNewName(''); }}>Cancel</button><button type="button" className="pf-admin-button" disabled={!newName.trim() || createSection.isPending} onClick={() => createSection.mutate()}>Create</button></div> : null}
    {location.isLoading ? <AdminSkeleton rows={4} /> : location.isError ? <AdminEmptyState icon={<Folder />} title="Question Bank content unavailable" description={location.error instanceof Error ? location.error.message : 'Try again.'} action={<button className="pf-admin-button" onClick={() => void refresh()}>Try again</button>} /> : data && (data.sections.length || data.questions.length) ? <div className="pf-question-bank-drive__list">
      {data.sections.map((section) => <article key={section.id}><button type="button" className="pf-question-bank-drive__open" onClick={() => setParentId(section.id)}><Folder size={20} /><span><strong>{section.name}</strong><small>{section._count.children ? `${section._count.children} subsections` : `${section._count.questions} questions`}</small></span></button>{renaming?.id === section.id ? <div className="pf-question-bank-drive__rename"><input className="pf-admin-input" value={renaming.name} onChange={(event) => setRenaming({ ...renaming, name: event.target.value })} /><button type="button" onClick={() => setRenaming(null)}>Cancel</button><button type="button" disabled={!renaming.name.trim() || renameSection.isPending} onClick={() => renameSection.mutate()}>Save</button></div> : <div className="pf-question-bank-drive__actions"><button type="button" onClick={() => setRenaming({ id: section.id, name: section.name })}>Rename</button><button type="button" onClick={() => { setMoveItem({ kind: 'section', id: section.id, name: section.name }); setMoveTarget(''); }}>Move</button><button type="button" disabled={Boolean(section._count.children || section._count.questions)} title={section._count.children || section._count.questions ? 'Only empty subsections can be deleted.' : undefined} onClick={() => { if (window.confirm(`Delete the empty subsection “${section.name}”?`)) removeSection.mutate(section.id); }}><Trash2 size={15} /></button></div>}</article>)}
      {data.questions.map((question) => <article key={question.id}><div className="pf-question-bank-drive__question"><FileQuestion size={19} /><span><strong>{plain(question.kind === 'CASE_MCQ' ? question.caseHtml : question.questionHtml) || 'Untitled question'}</strong><small>{labels[question.kind]} · {question.status} · {question.marks} mark{question.marks === 1 ? '' : 's'}</small></span></div><div className="pf-question-bank-drive__actions"><button type="button" onClick={() => { setMoveItem({ kind: 'question', id: question.id, name: plain(question.kind === 'CASE_MCQ' ? question.caseHtml : question.questionHtml) || 'Question' }); setMoveTarget(''); }}>Move</button></div></article>)}
    </div> : <AdminEmptyState icon={<Folder />} title="This location is empty" description="Create a subsection or add questions directly. Once one type is added, this location cannot contain the other type." />}
    <AdminDialog open={Boolean(moveItem)} onClose={() => { if (!move.isPending) setMoveItem(null); }} title={`Move ${moveItem?.kind ?? 'item'}`} description={moveItem?.name} size="small" footer={<><button type="button" className="pf-admin-button pf-admin-button--secondary" disabled={move.isPending} onClick={() => setMoveItem(null)}>Cancel</button><button type="button" className="pf-admin-button" disabled={move.isPending || (moveItem?.kind === 'question' && !moveTarget && Boolean(data?.allSections.length))} onClick={() => move.mutate()}>Move here</button></>}><label className="pf-admin-field"><span>Destination</span><AppSelect value={moveTarget} onChange={(event) => setMoveTarget(event.target.value)}><option value="">Question Bank root</option>{moveDestinations.map((section) => <option key={section.id} value={section.id}>{section.name}</option>)}</AppSelect><small>The destination must remain either a folder-only or question-only location.</small></label></AdminDialog>
  </section>;
}

function AddQuestions({ scope, academyId, courseId, files, banks, editing, initialQuestionBankId, initialQuestionBankSectionId, onDone, notify }: { scope: 'platform' | 'academy'; academyId?: string | null; courseId: string; files: LinkedFile[]; banks: QuestionBank[]; editing: WorkspaceQuestion | null; initialQuestionBankId: string; initialQuestionBankSectionId: string; onDone: () => void; notify: (title: string, message: string, tone?: AdminToastData['tone']) => void }) {
  const destinationBankId = editing?.questionBankId ?? initialQuestionBankId;
  const initialDestinationSectionId = editing?.questionBankSectionId ?? initialQuestionBankSectionId;
  const lockedToQuestionBank = Boolean(destinationBankId);
  const [method, setMethod] = useState<AddMethod>('manual'); const [mode, setMode] = useState<QuestionMode>(editing?.kind === 'CASE_MCQ' ? 'case' : 'normal'); const [area, setArea] = useState<'ORIGINAL' | 'QUESTION_BANK'>(editing?.practiceCollection === 'QUESTION_BANK' || destinationBankId ? 'QUESTION_BANK' : 'ORIGINAL'); const [questionBankId, setQuestionBankId] = useState(destinationBankId); const [destinationSectionId, setDestinationSectionId] = useState(initialDestinationSectionId); const [destinationReady, setDestinationReady] = useState(Boolean(editing));
  const selectedBank = banks.find((bank) => bank.id === questionBankId);
  const chooseBank = (id: string) => { setQuestionBankId(id); setDestinationSectionId(''); setDestinationReady(false); };
  const openDestination = (sectionId: string | null) => { setDestinationReady(false); setDestinationSectionId(sectionId ?? ''); };
  const showEditor = area !== 'QUESTION_BANK' || Boolean(editing) || (Boolean(questionBankId) && destinationReady);
  return <section className="pf-question-workspace">
    <header className="pf-question-add-header"><div><span>COURSE QUESTION BUILDER</span><h2>{editing ? 'Edit question' : 'Add questions'}</h2><p>Choose a collection and question type, then add it manually or import the exact template.</p></div>{!editing ? <div className="pf-question-method"><button className={method === 'manual' ? 'is-active' : ''} onClick={() => setMethod('manual')}><Edit3 /> Manual</button><button className={method === 'excel' ? 'is-active' : ''} onClick={() => setMethod('excel')}><FileSpreadsheet /> Excel import</button></div> : null}</header>
    {lockedToQuestionBank && editing ? <div className="pf-question-bank-destination"><strong>Question Bank question</strong><span>This record belongs to {selectedBank?.name ?? 'the selected Question Bank'}{destinationSectionId ? ' inside its current subsection' : ' at the Question Bank root'}.</span></div> : !lockedToQuestionBank ? <div className="pf-question-area-picker" aria-label="Question creation area"><button type="button" className={area === 'ORIGINAL' ? 'is-active' : ''} onClick={() => { setArea('ORIGINAL'); setQuestionBankId(''); setDestinationSectionId(''); setDestinationReady(false); }}><strong>MCQs</strong><span>Free or content-linked course practice</span></button><button type="button" className={area === 'QUESTION_BANK' ? 'is-active' : ''} onClick={() => setArea('QUESTION_BANK')}><strong>Question Bank</strong><span>Free or Store-entitled question collection</span></button></div> : null}
    {area === 'QUESTION_BANK' ? <label className="pf-question-bank-selector"><span>Destination Question Bank</span>{initialQuestionBankId && !editing ? <strong>{selectedBank?.name ?? 'Selected Question Bank'}</strong> : <AppSelect className="pf-admin-select" value={questionBankId} onChange={(event) => chooseBank(event.target.value)}><option value="">Select one Question Bank</option>{banks.filter((bank) => bank.status !== 'ARCHIVED').map((bank) => <option key={bank.id} value={bank.id}>{bank.name} · {bank.accessType} · {bank.status}</option>)}</AppSelect>}<small>{selectedBank ? `Every new question belongs only to ${selectedBank.name}. Normal and case-based MCQs may coexist.` : 'Select the single container that will own these questions.'}</small></label> : null}
    {area === 'QUESTION_BANK' && questionBankId && !editing ? <QuestionBankUploadNavigator scope={scope} academyId={academyId} bank={selectedBank} bankId={questionBankId} sectionId={destinationSectionId || null} onOpen={openDestination} onAvailability={setDestinationReady} /> : null}
    {showEditor ? <><div className="pf-question-kind-picker"><button className={mode === 'normal' ? 'is-active' : ''} onClick={() => setMode('normal')}><strong>Normal MCQ</strong><span>One prompt with four answer options.</span></button><button className={mode === 'case' ? 'is-active' : ''} onClick={() => setMode('case')}><strong>Case-based MCQ</strong><span>One passage with one or more sub-questions.</span></button></div>
    {method === 'manual' || editing ? <ManualEditor key={`${editing?.id ?? 'new'}-${mode}-${area}-${questionBankId}-${destinationSectionId}`} scope={scope} academyId={academyId} courseId={courseId} mode={mode} practiceCollection={area} questionBankId={questionBankId} questionBankSectionId={destinationSectionId} files={files} editing={editing} onDone={onDone} notify={notify} /> : <ExcelImport scope={scope} academyId={academyId} courseId={courseId} mode={mode} practiceCollection={area} questionBankId={questionBankId} questionBankSectionId={destinationSectionId} notify={notify} onDone={onDone} />}</> : area === 'QUESTION_BANK' && questionBankId ? <div className="pf-question-upload-gate"><Folder size={28} /><div><strong>Choose a final destination</strong><span>Open a subsection until you reach a location without child subsections. Questions can only be uploaded at that final level.</span></div></div> : null}
  </section>;
}

function QuestionBankUploadNavigator({ scope, academyId, bank, bankId, sectionId, onOpen, onAvailability }: { scope: 'platform' | 'academy'; academyId?: string | null; bank?: QuestionBank; bankId: string; sectionId: string | null; onOpen: (sectionId: string | null) => void; onAvailability: (available: boolean) => void }) {
  const location = useQuery({ queryKey: ['question-bank-upload-location', scope, academyId, bankId, sectionId], queryFn: () => questionWorkspaceApi.bankLocation(scope, academyId, bankId, sectionId), enabled: Boolean(bankId) });
  const data = location.data;
  const sections = data?.sections ?? [];
  const canUploadHere = Boolean(data) && sections.length === 0;
  useEffect(() => onAvailability(canUploadHere), [canUploadHere, onAvailability]);
  const parent = data && data.breadcrumbs.length > 1 ? data.breadcrumbs[data.breadcrumbs.length - 2]?.id ?? null : null;
  return <section className="pf-question-upload-browser" aria-label="Question Bank upload destination">
    <header><div><small>UPLOAD DESTINATION</small><strong>{bank?.name ?? data?.bank.name ?? 'Question Bank'}</strong><span>Browse the hierarchy and choose the final location for these questions.</span></div>{sectionId ? <button type="button" className="pf-admin-button pf-admin-button--secondary" onClick={() => onOpen(parent)}>Back one level</button> : null}</header>
    {data ? <nav className="pf-question-upload-browser__breadcrumbs" aria-label="Upload destination path">{data.breadcrumbs.map((item, index) => <button type="button" key={item.id ?? 'root'} onClick={() => onOpen(item.id)}>{index ? <ChevronRight size={14} /> : null}{item.name}</button>)}</nav> : null}
    {location.isLoading ? <AdminSkeleton rows={3} /> : location.isError ? <AdminEmptyState icon={<Folder />} title="Destination unavailable" description={location.error instanceof Error ? location.error.message : 'Try again.'} action={<button className="pf-admin-button" onClick={() => void location.refetch()}>Try again</button>} /> : sections.length ? <div className="pf-question-upload-browser__folders">{sections.map((section) => <button type="button" key={section.id} onClick={() => onOpen(section.id)}><Folder size={21} /><span><strong>{section.name}</strong><small>{section._count.children ? `${section._count.children} child subsection${section._count.children === 1 ? '' : 's'}` : `${section._count.questions} existing question${section._count.questions === 1 ? '' : 's'} · available for upload`}</small></span><ChevronRight size={18} /></button>)}</div> : data ? <div className="pf-question-upload-browser__selected"><CheckCircle2 size={20} /><div><strong>Questions will be uploaded here</strong><span>{data.breadcrumbs.map((item) => item.name).join(' / ')}{data.questions.length ? ` · ${data.questions.length} existing question${data.questions.length === 1 ? '' : 's'}` : ' · empty location'}</span></div></div> : null}
  </section>;
}

function ManualEditor({ scope, academyId, courseId, mode, practiceCollection, questionBankId, questionBankSectionId, files, editing, onDone, notify }: { scope: 'platform' | 'academy'; academyId?: string | null; courseId: string; mode: QuestionMode; practiceCollection: 'ORIGINAL' | 'QUESTION_BANK'; questionBankId: string; questionBankSectionId: string; files: LinkedFile[]; editing: WorkspaceQuestion | null; onDone: () => void; notify: (title: string, message: string, tone?: AdminToastData['tone']) => void }) {
  const [prompt, setPrompt] = useState(plain(mode === 'case' ? editing?.caseHtml : editing?.questionHtml)); const [marks, setMarks] = useState(String(editing?.marks ?? 1)); const [choices, setChoices] = useState(editing?.options?.length ? editing.options.map((item) => ({ ...item, html: plain(item.html) })) : options()); const [correct, setCorrect] = useState(editing?.correctOptionId ?? 'A'); const [correctExplanation, setCorrectExplanation] = useState(plain(editing?.correctExplanationHtml)); const [wrongExplanation, setWrongExplanation] = useState(plain(editing?.premiumWrongOptionsExplanationHtml)); const [examName, setExamName] = useState(editing?.examName ?? editing?.subQuestions[0]?.examName ?? ''); const [chapterName, setChapterName] = useState(editing?.chapterName ?? editing?.subQuestions[0]?.chapterName ?? ''); const [conceptName, setConceptName] = useState(editing?.conceptName ?? editing?.subQuestions[0]?.conceptName ?? ''); const [selectedFiles, setSelectedFiles] = useState(editing?.contentLinks.map((link) => link.contentItemId) ?? []); const [subs, setSubs] = useState(editing?.subQuestions.length ? editing.subQuestions.map((sub) => ({ ...sub, marks: sub.marks ?? 1, questionHtml: plain(sub.questionHtml), correctExplanationHtml: plain(sub.correctExplanationHtml), premiumWrongOptionsExplanationHtml: plain(sub.premiumWrongOptionsExplanationHtml), options: sub.options.map((item) => ({ ...item, html: plain(item.html) })) })) : [{ questionHtml: '', marks: 1, options: options(), correctOptionId: 'A', correctExplanationHtml: '', premiumWrongOptionsExplanationHtml: '', examName: '', chapterName: '', conceptName: '' }]);
  const savedExamAttempts = uniqueAttemptLabels([...(editing?.examAttempts ?? []), editing?.examName, editing?.subQuestions[0]?.examName]);
  const presentOptions = (items: Array<{ optionLabel: string; html: string }>) => items.filter((item) => item.html.trim()).map((item) => ({ ...item, html: asHtml(item.html) }));
  const validOptions = (items: Array<{ optionLabel: string; html: string }>, answer: string | null) => { const present = items.filter((item) => item.html.trim()); return present.length >= 2 && present.some((item) => item.optionLabel === answer); };
  const save = useMutation({ mutationFn: (status: 'DRAFT' | 'PUBLISHED') => { const classification = { examName: examName.trim(), chapterName: chapterName.trim(), conceptName: conceptName.trim() }; const bank = practiceCollection === 'QUESTION_BANK' ? { questionBankId, questionBankSectionId: questionBankSectionId || undefined } : {}; const payload: QuestionPayload = mode === 'normal' ? { kind: 'NORMAL_MCQ', marks: Number(marks), status, practiceCollection, ...bank, courseId, contentItemIds: selectedFiles, ...classification, questionHtml: asHtml(prompt), options: presentOptions(choices), correctOptionId: correct, correctExplanationHtml: asHtml(correctExplanation), premiumWrongOptionsExplanationHtml: asHtml(wrongExplanation) } : { kind: 'CASE_MCQ', marks: 1, status, practiceCollection, ...bank, courseId, contentItemIds: selectedFiles, examName: classification.examName, chapterName: '', conceptName: '', caseHtml: asHtml(prompt), subQuestions: subs.map((sub) => ({ questionHtml: asHtml(sub.questionHtml), marks: sub.marks, options: presentOptions(sub.options), correctOptionId: sub.correctOptionId, correctExplanationHtml: asHtml(sub.correctExplanationHtml || ''), premiumWrongOptionsExplanationHtml: asHtml(sub.premiumWrongOptionsExplanationHtml), examName: classification.examName, chapterName: sub.chapterName.trim(), conceptName: sub.conceptName.trim() })) }; return questionWorkspaceApi.save(scope, academyId, payload, editing?.id); }, onSuccess: (result, status) => { notify(result.revisionCreated ? 'Safe revision created' : status === 'PUBLISHED' ? 'Question published' : 'Draft saved', result.revisionCreated ? `The original student records were preserved and a ${status === 'PUBLISHED' ? 'published replacement' : 'new draft revision'} was created.` : 'File links, sub-question classification, marks and answer explanations were saved.'); onDone(); }, onError: (error) => notify('Question could not be saved', error instanceof Error ? error.message : 'Review all required fields.', 'error') });
  const validMarks = (value: number) => Number.isInteger(value) && value >= 1 && value <= 1_000;
  const valid = Boolean(courseId && (practiceCollection !== 'QUESTION_BANK' || questionBankId) && (practiceCollection === 'QUESTION_BANK' || selectedFiles.length > 0) && prompt.trim() && (mode === 'normal' ? chapterName.trim() && conceptName.trim() && validMarks(Number(marks)) && validOptions(choices, correct) : subs.length && subs.every((sub) => sub.chapterName.trim() && sub.conceptName.trim() && validMarks(sub.marks) && sub.questionHtml.trim() && validOptions(sub.options, sub.correctOptionId))));
  return <div className="pf-question-builder">
    <div className="pf-question-builder-main">
      {editing?._count?.practiceSessionQuestions ? <div className="pf-question-revision-notice" role="status"><strong>This question has student records.</strong><span>Classification, exam attempts, placement, and linked files can be updated safely. Changing question content, options, answers, explanations, marks, or case sub-questions will create a new revision and preserve the original history.</span></div> : null}
      <div className="pf-question-classification"><ExamAttemptField attempts={savedExamAttempts} value={examName} onChange={setExamName} />{mode === 'normal' ? <><label className="pf-admin-field"><span>Chapter name</span><input className="pf-admin-input" value={chapterName} onChange={(event) => setChapterName(event.target.value)} placeholder="e.g. Accounting Standards" /></label><label className="pf-admin-field"><span>Concept name</span><input className="pf-admin-input" value={conceptName} onChange={(event) => setConceptName(event.target.value)} placeholder="Internal weak-area classification" /></label><label className="pf-admin-field"><span>Marks</span><input className="pf-admin-input" type="number" min="1" max="1000" step="1" value={marks} onChange={(event) => setMarks(event.target.value)} /></label></> : null}</div>
      <label className="pf-admin-field"><span>{mode === 'case' ? 'Case passage' : 'Question'}</span><textarea className="pf-admin-input" rows={5} value={prompt} onChange={(event) => setPrompt(event.target.value)} /></label>
      {mode === 'normal' ? <McqOptions choices={choices} correct={correct} onCorrect={setCorrect} onChange={setChoices} /> : <div className="pf-case-list">{subs.map((sub, index) => <section className="pf-case-subquestion" key={index}>
        <header><strong>Sub-question {index + 1}</strong>{subs.length > 1 ? <button type="button" aria-label={`Remove sub-question ${index + 1}`} onClick={() => setSubs(subs.filter((_, itemIndex) => itemIndex !== index))}><X /></button> : null}</header>
        <textarea className="pf-admin-input" rows={3} value={sub.questionHtml} onChange={(event) => setSubs(subs.map((item, itemIndex) => itemIndex === index ? { ...item, questionHtml: event.target.value } : item))} placeholder="Sub-question" />
        <div className="pf-question-classification"><label className="pf-admin-field"><span>Chapter name</span><input className="pf-admin-input" value={sub.chapterName} onChange={(event) => setSubs(subs.map((item, itemIndex) => itemIndex === index ? { ...item, chapterName: event.target.value } : item))} placeholder="Required for this sub-question" /></label><label className="pf-admin-field"><span>Concept name</span><input className="pf-admin-input" value={sub.conceptName} onChange={(event) => setSubs(subs.map((item, itemIndex) => itemIndex === index ? { ...item, conceptName: event.target.value } : item))} placeholder="Required for this sub-question" /></label><label className="pf-admin-field"><span>Marks</span><input className="pf-admin-input" type="number" min="1" max="1000" step="1" value={sub.marks} onChange={(event) => setSubs(subs.map((item, itemIndex) => itemIndex === index ? { ...item, marks: Number(event.target.value) } : item))} /></label></div>
        <McqOptions choices={sub.options} correct={sub.correctOptionId || 'A'} onCorrect={(value) => setSubs(subs.map((item, itemIndex) => itemIndex === index ? { ...item, correctOptionId: value } : item))} onChange={(value) => setSubs(subs.map((item, itemIndex) => itemIndex === index ? { ...item, options: value } : item))} />
        <div className="pf-question-explanations"><label><span>Correct explanation</span><textarea className="pf-admin-input" rows={3} value={sub.correctExplanationHtml} onChange={(event) => setSubs(subs.map((item, itemIndex) => itemIndex === index ? { ...item, correctExplanationHtml: event.target.value } : item))} placeholder="Explain why the correct answer is right" /></label><label><span>Wrong options explanation</span><textarea className="pf-admin-input" rows={3} value={sub.premiumWrongOptionsExplanationHtml} onChange={(event) => setSubs(subs.map((item, itemIndex) => itemIndex === index ? { ...item, premiumWrongOptionsExplanationHtml: event.target.value } : item))} placeholder="Explain why the other options are wrong" /></label></div>
      </section>)}<button type="button" className="pf-admin-button pf-admin-button--secondary" onClick={() => setSubs([...subs, { questionHtml: '', marks: 1, options: options(), correctOptionId: 'A', correctExplanationHtml: '', premiumWrongOptionsExplanationHtml: '', examName, chapterName: '', conceptName: '' }])}><Plus size={16} /> Add sub-question</button></div>}
      {mode === 'normal' ? <div className="pf-question-explanations"><label><span>Correct explanation</span><textarea className="pf-admin-input" rows={3} value={correctExplanation} onChange={(event) => setCorrectExplanation(event.target.value)} /></label><label><span>Wrong options explanation</span><textarea className="pf-admin-input" rows={3} value={wrongExplanation} onChange={(event) => setWrongExplanation(event.target.value)} /></label></div> : null}
    </div>
    <FilePicker files={files} selected={selectedFiles} onChange={setSelectedFiles} required={practiceCollection !== 'QUESTION_BANK'} />
    <footer className="pf-question-workspace__actions"><button type="button" className="pf-admin-button pf-admin-button--secondary" disabled={!valid || save.isPending} onClick={() => save.mutate('DRAFT')}>Save draft</button><button type="button" className="pf-admin-button" disabled={!valid || save.isPending} onClick={() => save.mutate('PUBLISHED')}><Send size={16} /> Publish</button></footer>
  </div>;
}

function ExamAttemptField({ attempts, value, onChange }: { attempts: string[]; value: string; onChange: (value: string) => void }) {
  const [adding, setAdding] = useState(false);
  const selectedAttempt = attempts.find((attempt) => attempt.toLocaleLowerCase() === value.trim().toLocaleLowerCase()) ?? attempts[0] ?? '';
  if (!attempts.length) return <label className="pf-admin-field"><span>Exam attempt (optional)</span><input className="pf-admin-input" value={value} maxLength={160} onChange={(event) => onChange(event.target.value)} placeholder="e.g. Mar 2026" /></label>;
  return <label className="pf-admin-field pf-exam-attempt-field">
    <span>Exam attempts (optional)</span>
    <AppSelect aria-label="Saved exam attempts" value={adding ? '__add__' : selectedAttempt} onChange={(event) => { if (event.target.value === '__add__') { setAdding(true); onChange(''); } else { setAdding(false); onChange(event.target.value); } }}>
      {attempts.map((attempt) => <option key={attempt} value={attempt}>{attempt}</option>)}
      <option value="__add__">+ Add another attempt</option>
    </AppSelect>
    {adding ? <input className="pf-admin-input" value={value} maxLength={160} onChange={(event) => onChange(event.target.value)} placeholder="e.g. Jul 2026" autoFocus /> : null}
    <small>{attempts.length} saved exam {attempts.length === 1 ? 'attempt' : 'attempts'}</small>
  </label>;
}

function McqOptions({ choices, correct, onCorrect, onChange }: { choices: Array<{ optionLabel: string; html: string }>; correct: string; onCorrect: (value: string) => void; onChange: (value: Array<{ optionLabel: string; html: string }>) => void }) { return <div className="pf-question-options">{choices.map((choice, index) => <label className="pf-question-option" key={choice.optionLabel}><span className="pf-question-option__choice"><input type="radio" checked={correct === choice.optionLabel} onChange={() => onCorrect(choice.optionLabel)} /><span>{choice.optionLabel}</span></span><span><small>Option {choice.optionLabel}</small><input className="pf-admin-input" value={choice.html} onChange={(event) => onChange(choices.map((item, itemIndex) => itemIndex === index ? { ...item, html: event.target.value } : item))} /></span></label>)}</div>; }

function ExcelImport({ scope, academyId, courseId, mode, practiceCollection, questionBankId, questionBankSectionId, notify, onDone }: { scope: 'platform' | 'academy'; academyId?: string | null; courseId: string; mode: QuestionMode; practiceCollection: 'ORIGINAL' | 'QUESTION_BANK'; questionBankId: string; questionBankSectionId: string; notify: (title: string, message: string, tone?: AdminToastData['tone']) => void; onDone: () => void }) {
  const [file, setFile] = useState<File | null>(null); const [contentBase64, setContentBase64] = useState(''); const [result, setResult] = useState<any>(null);
  const template = useMutation({ mutationFn: () => questionWorkspaceApi.template(scope, academyId, mode), onSuccess: download, onError: (error) => notify('Template unavailable', error instanceof Error ? error.message : 'Try again.', 'error') });
  const validate = useMutation({ mutationFn: async () => { if (!file) throw new Error('Choose the completed .xlsx template.'); if (practiceCollection === 'QUESTION_BANK' && !questionBankId) throw new Error('Select the destination Question Bank first.'); const base64 = await fileBase64(file); setContentBase64(base64); return questionWorkspaceApi.validateImport(scope, academyId, { courseId, mode, practiceCollection, questionBankId: questionBankId || undefined, questionBankSectionId: questionBankSectionId || undefined, fileName: file.name, contentBase64: base64 }); }, onSuccess: setResult, onError: (error) => notify('Validation failed', error instanceof Error ? error.message : 'Try again.', 'error') });
  const commit = useMutation({ mutationFn: () => questionWorkspaceApi.commitImport(scope, academyId, { courseId, mode, practiceCollection, questionBankId: questionBankId || undefined, questionBankSectionId: questionBankSectionId || undefined, fileName: file!.name, contentBase64, validationDigest: result.validationDigest }), onSuccess: (response) => { notify('Import complete', `${response.imported} questions were appended in one transaction.`); onDone(); }, onError: (error) => notify('Import was not committed', error instanceof Error ? error.message : 'No questions were inserted.', 'error') });
  const clearFile = () => { setFile(null); setContentBase64(''); setResult(null); };
  const fileSize = file ? `${Math.max(1, Math.round(file.size / 1024))} KB` : '';
  return <div className="pf-question-import">
    <div className="pf-question-import__intro"><div><small>SERVER-VALIDATED EXCEL</small><h2>{mode === 'normal' ? 'Normal MCQ template' : 'Case MCQ template'}</h2><p>Use the exact template, select the completed workbook, validate every row, then confirm one atomic database import.</p></div><button type="button" className="pf-admin-button pf-admin-button--secondary" disabled={template.isPending} onClick={() => template.mutate()}><Download size={16} /> Download exact template</button></div>
    <label className={`pf-question-dropzone${file ? ' has-file' : ''}`}>
      {file ? <FileSpreadsheet size={34} /> : <UploadCloud size={35} />}
      <strong>{file?.name ?? 'Select completed .xlsx workbook'}</strong>
      <span>{file ? 'Selected locally — choose Validate workbook to send it securely.' : 'Drop it here or browse from this device. Maximum size 20 MB.'}</span>
      <input key={file ? `${file.name}-${file.lastModified}` : 'empty'} type="file" accept=".xlsx" hidden onChange={(event) => { const nextFile = event.target.files?.[0] ?? null; setFile(nextFile); setContentBase64(''); setResult(null); }} />
    </label>
    {file ? <section className="pf-question-upload-receipt" aria-live="polite"><FileSpreadsheet size={22} /><div><strong>{file.name}</strong><span>{fileSize} · Excel workbook</span></div><span className={`pf-question-upload-status${result ? result.valid ? ' is-valid' : ' is-error' : ''}`}>{result ? result.valid ? 'Validated' : 'Needs corrections' : 'Ready to validate'}</span><button type="button" onClick={clearFile}>Remove</button></section> : null}
    <div className="pf-question-import__actions"><button type="button" className="pf-admin-button" disabled={!file || validate.isPending || (practiceCollection === 'QUESTION_BANK' && !questionBankId)} onClick={() => validate.mutate()}>{validate.isPending ? 'Validating…' : result ? 'Validate again' : 'Validate workbook'}</button></div>
    {result ? <section className={`pf-question-import-result ${result.valid ? 'is-valid' : 'is-error'}`}><header><strong>{result.valid ? 'Workbook received and validated' : 'Workbook received — corrections required'}</strong><span>{result.totalRows} rows · {result.questionCount} questions · {result.errors.length} errors</span></header>{result.errors.length ? <div className="pf-question-import-errors">{result.errors.map((error: any, index: number) => <p key={`${error.row}-${error.field}-${index}`}><b>Row {error.row} · {error.field}</b>{error.problem}</p>)}</div> : <button type="button" className="pf-admin-button" disabled={commit.isPending} onClick={() => commit.mutate()}><CheckCircle2 size={16} /> {commit.isPending ? 'Importing…' : 'Confirm atomic import'}</button>}</section> : null}
  </div>;
}

function Explanation({ title, html }: { title: string; html?: string }) { return plain(html) ? <div className="pf-question-explanation"><strong>{title}</strong><div dangerouslySetInnerHTML={{ __html: html ?? '' }} /></div> : null; }

function QuestionDetails({ question }: { question: WorkspaceQuestion }) { return <div className="pf-question-details"><div className="pf-question-filechips">{question.contentLinks.map((link) => <span key={link.contentItemId}>{link.contentItem.name} · {link.contentItem.accessType}</span>)}</div><section><h3>{question.kind === 'CASE_MCQ' ? 'Case details' : 'Classification'}</h3><div className="pf-question-metadata"><span><small>Exam attempts</small>{question.examAttempts.length ? question.examAttempts.join(', ') : '—'}</span>{question.kind === 'NORMAL_MCQ' ? <><span><small>Chapter</small>{question.chapterName || '—'}</span><span><small>Concept</small>{question.conceptName || '—'}</span><span><small>Marks</small>{question.marks}</span></> : null}</div></section><section><h3>{question.kind === 'CASE_MCQ' ? 'Case passage' : 'Question'}</h3><div dangerouslySetInnerHTML={{ __html: question.kind === 'CASE_MCQ' ? question.caseHtml : question.questionHtml }} /></section>{question.kind === 'NORMAL_MCQ' ? <section><h3>Options</h3>{question.options.map((option) => <p key={option.optionLabel}><b>{option.optionLabel}{option.optionLabel === question.correctOptionId ? ' ✓' : ''}</b> <span dangerouslySetInnerHTML={{ __html: option.html }} /></p>)}<Explanation title="Correct answer explanation" html={question.correctExplanationHtml} /><Explanation title="Wrong options explanation" html={question.premiumWrongOptionsExplanationHtml} /></section> : question.subQuestions.map((sub, index) => <section key={sub.id ?? index}><h3>Sub-question {index + 1}</h3><div className="pf-question-metadata"><span><small>Chapter</small>{sub.chapterName || '—'}</span><span><small>Concept</small>{sub.conceptName || '—'}</span><span><small>Marks</small>{sub.marks}</span></div><div dangerouslySetInnerHTML={{ __html: sub.questionHtml }} />{sub.options.map((option) => <p key={option.optionLabel}><b>{option.optionLabel}{option.optionLabel === sub.correctOptionId ? ' ✓' : ''}</b> <span dangerouslySetInnerHTML={{ __html: option.html }} /></p>)}<Explanation title="Correct answer explanation" html={sub.correctExplanationHtml} /><Explanation title="Wrong options explanation" html={sub.premiumWrongOptionsExplanationHtml} /></section>)}</div>; }
